var textForPages =["\u041d\u043e\u0432\u043e\u0441\u0442\u043d\u043e\u0439 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 28 \u043d\u043e\u044f\u0431\u0440\u044f \u2014 5 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a01 09\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u000d\u000a\u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0432 \u0432\u044b\u043f\u0443\u0441\u043a\u0435\u000d\u000a\u0421\u0428\u0410 \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0438 \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0435 \u0441\u0434\u0435\u043b\u043a\u0438 \u000d\u000a\u0441 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0435\u0439 \u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u043e\u043c \u2028\u000d\u000a\u043d\u0430 $1,5 \u043c\u043b\u0440\u0434\u000d\u000a\u0421\u0428\u0410 \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u044e\u0442 \u0432\u043e\u0435\u043d\u043d\u043e\u0435 \u043f\u0430\u0440\u0442\u043d\u0435\u0440\u0441\u0442\u0432\u043e \u0441 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u0438\u043c \u000d\u000a\u0437\u0430\u043b\u0438\u0432\u043e\u043c. \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043f\u043e\u043b\u0443\u0447\u0438\u0442 \u0443\u0441\u043b\u0443\u0433\u0438 \u000d\u000a\u043f\u043e \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044e \u0438 \u043e\u0431\u043e\u0440\u0443\u0434\u043e\u0432\u0430\u043d\u0438\u0435 \u0434\u043b\u044f \u0432\u0435\u0440\u0442\u043e\u043b\u0435\u0442\u043e\u0432, \u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u2014 \u0441\u0435\u0440\u0432\u0438\u0441 \u0438\u0441\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0435\u0439 F-16.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043e\u0442\u043a\u0440\u044b\u043b\u0430 \u0442\u0435\u043d\u0434\u0435\u0440 \u000d\u000a\u043d\u0430 \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0445 \u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0445\u000d\u000a\u041a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u043d\u0430 \u043f\u043b\u043e\u0449\u0430\u0434\u0438 \u000d\u000a13 \u0442\u044b\u0441. \u043a\u043c\u00b2 \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 Vision 2030. \u0423\u0447\u0430\u0441\u0442\u043a\u0438 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442 \u000d\u000a\u043f\u0435\u0440\u0441\u043f\u0435\u043a\u0442\u0438\u0432\u043d\u044b\u0435 \u0437\u0430\u043f\u0430\u0441\u044b \u0437\u043e\u043b\u043e\u0442\u0430, \u0441\u0435\u0440\u0435\u0431\u0440\u0430, \u043c\u0435\u0434\u0438 \u0438 \u0446\u0438\u043d\u043a\u0430.\u000d\u000a\u0415\u0433\u0438\u043f\u0435\u0442 \u0445\u043e\u0447\u0435\u0442 \u0440\u0430\u0437\u0432\u0435\u0434\u0430\u0442\u044c \u043c\u0438\u043d\u0440\u0435\u0441\u0443\u0440\u0441\u044b \u000d\u000a\u0441 \u043f\u043e\u043c\u043e\u0449\u044c\u044e \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439\u000d\u000a\u0421\u0442\u0440\u0430\u043d\u0430 \u0441\u043d\u0438\u0436\u0430\u0435\u0442 \u0431\u0430\u0440\u044c\u0435\u0440\u044b \u0432\u0445\u043e\u0434\u0430 \u0438 \u0432\u0432\u043e\u0434\u0438\u0442 \u043d\u0430\u043b\u043e\u0433\u043e\u0432\u044b\u0435 \u000d\u000a\u043b\u044c\u0433\u043e\u0442\u044b, \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u044f \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u0434\u043e\u043b\u044e \u0441\u0435\u043a\u0442\u043e\u0440\u0430 \u000d\u000a\u0432 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0435 \u0441 1% \u0434\u043e 6% \u0437\u0430 10 \u043b\u0435\u0442.\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u044f \u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043e\u0442\u043c\u0435\u043d\u0438\u043b\u0438 \u0432\u0438\u0437\u044b\u000d\u000a\u0413\u0440\u0430\u0436\u0434\u0430\u043d\u0435 \u043e\u0431\u0435\u0438\u0445 \u0441\u0442\u0440\u0430\u043d \u0441\u043c\u043e\u0433\u0443\u0442 \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c\u0441\u044f \u000d\u000a\u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0430 \u0434\u043e 90 \u0434\u043d\u0435\u0439 \u0432 \u0433\u043e\u0434\u0443 \u0431\u0435\u0437 \u000d\u000a\u043e\u0444\u043e\u0440\u043c\u043b\u0435\u043d\u0438\u044f \u0432\u0438\u0437\u044b. \u0421\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u0432\u0441\u0442\u0443\u043f\u0438\u0442 \u0432 \u0441\u0438\u043b\u0443 \u0447\u0435\u0440\u0435\u0437 \u000d\u000a60 \u0434\u043d\u0435\u0439.\u000d\u000aInvestcorp \u0441\u0442\u0430\u043b\u0430 \u044f\u043a\u043e\u0440\u043d\u044b\u043c \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u043c \u000d\u000aChuangxin Industries\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u0438 \u000d\u000a\u043d\u0430 $813 \u043c\u043b\u043d. \u041f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u0441\u0440\u0435\u0434\u0441\u0442\u0432 \u043f\u043e\u0439\u0434\u0435\u0442 \u000d\u000a\u043d\u0430 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u043e\u0433\u043e \u0437\u0430\u0432\u043e\u0434\u0430 \u0432 \u042f\u043d\u0431\u0443 \u000d\u000a(\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f).\u000d\u000aMP Materials \u0438 Maaden \u0441\u043e\u0437\u0434\u0430\u044e\u0442 \u0421\u041f \u000d\u000a\u043f\u043e \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u043c \u043c\u0435\u0442\u0430\u043b\u043b\u0430\u043c\u000d\u000a\u0421\u0434\u0435\u043b\u043a\u0430 \u043f\u0440\u0438\u0437\u0432\u0430\u043d\u0430 \u0443\u043a\u0440\u0435\u043f\u0438\u0442\u044c \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u0443 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u043c \u000d\u000a\u0446\u0435\u043f\u043e\u0447\u043a\u0430\u043c \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a. Maaden \u043f\u043e\u043b\u0443\u0447\u0438\u0442 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0439 \u000d\u000a\u043f\u0430\u043a\u0435\u0442, \u0430 MP Materials \u0432\u043d\u0435\u0441\u0435\u0442 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u000d\u000a\u044d\u043a\u0441\u043f\u0435\u0440\u0442\u0438\u0437\u0443.\u000d\u000aAya \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0438\u043b\u0430 \u0437\u0430\u043f\u0430\u0441\u044b \u0440\u0443\u0434\u044b \u0432 \u041c\u0430\u0440\u043e\u043a\u043a\u043e\u000d\u000a\u041f\u0440\u043e\u0435\u043a\u0442 Boumadine \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b \u0431\u043e\u0433\u0430\u0442\u0443\u044e \u000d\u000a\u043c\u0438\u043d\u0435\u0440\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u0441 \u0432\u044b\u0441\u043e\u043a\u0438\u043c\u0438 \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0446\u0438\u044f\u043c\u0438 \u0437\u043e\u043b\u043e\u0442\u0430 \u000d\u000a\u0438 \u0441\u0435\u0440\u0435\u0431\u0440\u0430. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0433\u043e\u0442\u043e\u0432\u0438\u0442 \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0443 \u043a\u0430\u0440\u044c\u0435\u0440\u043e\u0432 \u000d\u000a\u0438 \u043f\u043e\u0434\u0437\u0435\u043c\u043d\u044b\u0445 \u0448\u0430\u0445\u0442.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043e\u0436\u0438\u0434\u0430\u0435\u0442 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u044f \u000d\u000a\u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430 \u0431\u044e\u0434\u0436\u0435\u0442\u0430\u000d\u000a\u0411\u044e\u0434\u0436\u0435\u0442\u043d\u044b\u0439 \u0440\u0430\u0437\u0440\u044b\u0432 \u043c\u043e\u0436\u0435\u0442 \u0441\u043d\u0438\u0437\u0438\u0442\u044c\u0441\u044f \u0441 $65,3 \u043c\u043b\u0440\u0434 \u000d\u000a\u0434\u043e $44,1 \u043c\u043b\u0440\u0434 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u043a\u0435 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 \u000d\u000a\u0438 \u0441\u043b\u0430\u0431\u043e\u043c\u0443 \u0440\u043e\u0441\u0442\u0443 \u043d\u0435\u0444\u0442\u044f\u043d\u044b\u0445 \u0434\u043e\u0445\u043e\u0434\u043e\u0432.\u000d\u000aDP World \u0441\u0442\u0440\u043e\u0438\u0442 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u0443\u044e \u043b\u0438\u043d\u0438\u044e \u000d\u000a\u0432 \u043f\u043e\u0440\u0442\u0443 \u0424\u0440\u0438\u043c\u0430\u043d\u0442\u043b\u000d\u000a\u041b\u0438\u043d\u0438\u044f \u0437\u0430 $18 \u043c\u043b\u043d \u0441\u0432\u044f\u0436\u0435\u0442 \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u000d\u000a\u0441 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u044b\u043c \u0443\u0437\u043b\u043e\u043c \u043f\u043e\u0440\u0442\u0430. \u042d\u0442\u043e \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442 \u0434\u043e\u043b\u044e \u000d\u000a\u0436/\u0434 \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u043e\u043a \u0438 \u0441\u043d\u0438\u0437\u0438\u0442 \u043d\u0430\u0433\u0440\u0443\u0437\u043a\u0443 \u043d\u0430 \u0434\u043e\u0440\u043e\u0433\u0438.\u000d\u000a\u0415\u0433\u0438\u043f\u0435\u0442 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0438\u0440\u0443\u0435\u0442 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u000d\u000a\u0442\u0440\u0430\u0444\u0438\u043a\u0430 \u0447\u0435\u0440\u0435\u0437 \u0421\u0443\u044d\u0446\u000d\u000a\u041f\u043e\u0441\u043b\u0435 \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u044f \u0432 \u0413\u0430\u0437\u0435 \u0442\u0440\u0430\u043d\u0437\u0438\u0442 \u043f\u043e\u0441\u0442\u0435\u043f\u0435\u043d\u043d\u043e \u000d\u000a\u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u043a \u043f\u0440\u0435\u0436\u043d\u0438\u043c \u0443\u0440\u043e\u0432\u043d\u044f\u043c. \u0414\u043e\u0445\u043e\u0434\u044b \u043a\u0430\u043d\u0430\u043b\u0430 \u000d\u000a\u0432 \u043e\u043a\u0442\u044f\u0431\u0440\u0435 \u0438 \u043d\u043e\u044f\u0431\u0440\u0435 \u043f\u0440\u0435\u0432\u044b\u0441\u0438\u043b\u0438 $370 \u043c\u043b\u043d.","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 28 \u043d\u043e\u044f\u0431\u0440\u044f \u2014 5 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aMP Materials \u0438 Maaden \u0437\u0430\u0439\u043c\u0443\u0442\u0441\u044f \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u043e\u0439 \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u0432 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438\u000d\u000a\u041f\u0440\u043e\u0435\u043a\u0442 \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u0435\u0442 \u0440\u043e\u043b\u044c \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430 \u0432 \u0446\u0435\u043f\u043e\u0447\u043a\u0430\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u044b\u0445 \u2028\u000d\u000a\u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u0432\u043d\u0435 \u041a\u0438\u0442\u0430\u044f.\u000d\u000a\u0410\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0430\u044f MP Materials \u0438 \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u000d\u000aMaaden \u043f\u0440\u0438 \u0443\u0447\u0430\u0441\u0442\u0438\u0438 \u041f\u0435\u043d\u0442\u0430\u0433\u043e\u043d\u0430 \u000d\u000a\u043e\u0431\u044f\u0437\u044b\u0432\u0430\u044e\u0449\u0435\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0438 \u2028\u000d\u000a\u0421\u041f \u043f\u043e \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0435 \u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u0432 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438. \u000a\u000d\u000aMaaden \u043f\u043e\u043b\u0443\u0447\u0438\u0442 51% \u0421\u041f, \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u0430\u044f \u0434\u043e\u043b\u044f \u000d\u000a\u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0430\u0442\u044c \u041f\u0435\u043d\u0442\u0430\u0433\u043e\u043d\u0443 \u2028\u000d\u000a\u0438 MP Materials, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0442 \u000d\u000a\u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u044d\u043a\u0441\u043f\u0435\u0440\u0442\u0438\u0437\u0443. \u041f\u0440\u043e\u0435\u043a\u0442 \u0441\u0442\u0430\u043b \u000d\u000a\u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u0448\u0430\u0433\u043e\u043c \u043d\u0430 \u0444\u043e\u043d\u0435 \u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f\u000d\u000a\u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0438\u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a MP Materials \u0432 \u041a\u0438\u0442\u0430\u0439 \u0438\u0437-\u0437\u0430 \u043d\u043e\u0432\u044b\u0445 \u000d\u000a\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439.\u000a\u000d\u000aMP Materials \u0432\u043b\u0430\u0434\u0435\u0435\u0442 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435\u043c \u000d\u000aMountain Pass \u2014 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c \u0432 \u0421\u0428\u0410 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0435\u043c \u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u0438 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0435 \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u044b\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432. \u0421\u0434\u0435\u043b\u043a\u0430 \u0441 Maaden \u000d\u000a\u0441\u0442\u0430\u043b\u0430 \u0434\u043b\u044f \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0432\u0430\u0436\u043d\u044b\u043c \u000d\u000a\u0448\u0430\u0433\u043e\u043c \u043f\u043e\u0441\u043b\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043f\u0440\u0435\u043a\u0440\u0430\u0442\u0438\u0442\u044c \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u0440\u0435\u0434\u043a\u043e\u0437\u0435\u043c\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0442\u0430 \u0432 \u041a\u0438\u0442\u0430\u0439 \u000d\u000a\u043d\u0430 \u0444\u043e\u043d\u0435 \u043d\u043e\u0432\u044b\u0445 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0445 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u0442\u0435\u043d\u0434\u0435\u0440 \u043d\u0430 \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u000d\u000a\u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0445 \u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0445\u000d\u000a\u0422\u0435\u043d\u0434\u0435\u0440 \u0441\u0442\u0430\u043b \u0447\u0430\u0441\u0442\u044c\u044e \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0438 \u043f\u043e \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u044e \u0434\u043e\u0431\u044b\u0447\u0438 \u0438 \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0438 \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u2028\u000d\u000aVision 2030. \u041e\u0431\u0449\u0438\u0439 \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0432 $2,5 \u0442\u0440\u043b\u043d.\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u043f\u0440\u0438\u0435\u043c \u000d\u000a\u0437\u0430\u044f\u0432\u043e\u043a \u043d\u0430 \u0442\u0440\u0438 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u043d\u0430 \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u000d\u000a\u043f\u043b\u043e\u0449\u0430\u0434\u044c\u044e 13 \u0442\u044b\u0441. \u043a\u043c\u00b2. \u0423\u0447\u0430\u0441\u0442\u043a\u0438 \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u044b \u000d\u000a\u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f\u0445 \u041c\u0435\u0434\u0438\u043d\u0430, \u041c\u0435\u043a\u043a\u0430, \u042d\u0440-\u0420\u0438\u044f\u0434, \u2028\u000d\u000a\u042d\u043b\u044c-\u041a\u0430\u0441\u0438\u043c \u0438 \u0425\u0430\u0438\u043b\u044c \u0438 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442 \u043f\u0435\u0440\u0441\u043f\u0435\u043a\u0442\u0438\u0432\u043d\u044b\u0435 \u000d\u000a\u0437\u0430\u043f\u0430\u0441\u044b \u0437\u043e\u043b\u043e\u0442\u0430, \u0441\u0435\u0440\u0435\u0431\u0440\u0430, \u043c\u0435\u0434\u0438 \u0438 \u0446\u0438\u043d\u043a\u0430.\u000a\u000d\u000a\u0420\u0430\u0443\u043d\u0434 \u0434\u043e\u043b\u0436\u0435\u043d \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u043e\u0431\u044a\u0435\u043c \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u000d\u000a\u0432 \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443, \u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u0431\u0430\u0437\u0443 \u0433\u0435\u043e\u0434\u0430\u043d\u043d\u044b\u0445 \u0438 \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u000d\u000a\u0440\u0430\u0431\u043e\u0447\u0438\u0435 \u043c\u0435\u0441\u0442\u0430. \u041f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0441\u0442\u0438\u043c\u0443\u043b\u0438\u0440\u0443\u0435\u0442 \u000d\u000a\u043e\u0442\u0440\u0430\u0441\u043b\u044c \u0447\u0435\u0440\u0435\u0437 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0443 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438, \u000d\u000a\u043a\u043e\u043c\u043f\u0435\u043d\u0441\u0438\u0440\u0443\u044e\u0449\u0443\u044e \u0447\u0430\u0441\u0442\u044c \u0437\u0430\u0442\u0440\u0430\u0442 \u000d\u000a\u043d\u0430 \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443.\u000d\u000a\u043d\u0430\u0447\u0430\u043b\u043e\u000d\u000a02 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 28 \u043d\u043e\u044f\u0431\u0440\u044f \u2014 5 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aAya \u0432\u044b\u044f\u0432\u0438\u043b\u0430 \u043d\u043e\u0432\u044b\u0435 \u0437\u0430\u043b\u0435\u0436\u0438 \u0440\u0443\u0434\u044b \u043d\u0430 \u043f\u0440\u043e\u0435\u043a\u0442\u0435 \u000d\u000aBoumadine \u0432 \u041c\u0430\u0440\u043e\u043a\u043a\u043e \u000d\u000aAya \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0438\u0442 85% \u043f\u0440\u043e\u0435\u043a\u0442\u0430 Boumadine \u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u042d\u0440-\u0420\u0430\u0448\u0438\u0434\u0438\u044f \u043d\u0435\u0434\u0430\u043b\u0435\u043a\u043e \u043e\u0442 \u0430\u043b\u0436\u0438\u0440\u0441\u043a\u043e\u0439 \u000d\u000a\u0433\u0440\u0430\u043d\u0438\u0446\u044b. Boumadine \u2014 \u043e\u0434\u0438\u043d \u0438\u0437 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438, \u0435\u0433\u043e \u043e\u0446\u0435\u043d\u043a\u0430 \u2014 $3 \u043c\u043b\u0440\u0434.\u000d\u000aAya Gold & Silver \u043e \u0440\u0435\u043a\u043e\u0440\u0434\u043d\u043e\u043c \u000d\u000a\u043f\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043d\u0438\u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0438 \u0432\u044b\u044f\u0432\u043b\u0435\u043d\u0438\u0438 \u000d\u000a\u043d\u043e\u0432\u043e\u0439 \u0432\u044b\u0441\u043e\u043a\u043e\u0441\u043e\u0440\u0442\u043d\u043e\u0439 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u043d\u0430 \u043f\u0440\u043e\u0435\u043a\u0442\u0435 \u000d\u000aBoumadine. \u0421\u043a\u0432\u0430\u0436\u0438\u043d\u0430 BOU-MP25-087 \u000d\u000a\u043f\u043e\u043a\u0430\u0437\u0430\u043b\u0430 15-\u043c\u0435\u0442\u0440\u043e\u0432\u044b\u0439 \u0438\u043d\u0442\u0435\u0440\u0432\u0430\u043b \u000d\u000a\u0441 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043d\u0438\u0435\u043c 3,31 \u0433 \u043d\u0430 \u0442\u043e\u043d\u043d\u0443 \u0437\u043e\u043b\u043e\u0442\u0430, 1900 \u0433 \u000d\u000a\u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u043d\u0430 \u0442\u043e\u043d\u043d\u0443 \u0441\u0435\u0440\u0435\u0431\u0440\u0430, 4,8% \u0446\u0438\u043d\u043a\u0430, 1,8% \u0441\u0432\u0438\u043d\u0446\u0430 \u000d\u000a\u0438 0,03% \u043c\u0435\u0434\u0438.\u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u0448\u0435\u0441\u0442\u044c \u000d\u000a\u043a\u0430\u0440\u044c\u0435\u0440\u043e\u0432 \u0438 \u0442\u0440\u0438 \u043f\u043e\u0434\u0437\u0435\u043c\u043d\u044b\u0435 \u0448\u0430\u0445\u0442\u044b \u0441\u043e \u0441\u0440\u043e\u043a\u043e\u043c \u000d\u000a\u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0430\u0446\u0438\u0438 11 \u043b\u0435\u0442 \u043f\u0440\u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 8 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0440\u0443\u0434\u044b \u0432 \u0441\u0443\u0442\u043a\u0438.\u000d\u000a#\u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u044f\u000d\u000a\u0421\u0428\u0410 \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0438 \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0435 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u044b \u2028\u000d\u000a\u0441 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0435\u0439 \u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u043e\u043c \u043d\u0430 $1,5 \u043c\u043b\u0440\u0434\u000d\u000a\u042d\u0442\u043e\u0442 \u0448\u0430\u0433 \u043f\u043e\u0434\u0447\u0435\u0440\u043a\u0438\u0432\u0430\u0435\u0442 \u0443\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0438\u0435 \u043e\u0431\u043e\u0440\u043e\u043d\u043d\u043e\u0433\u043e \u043f\u0430\u0440\u0442\u043d\u0435\u0440\u0441\u0442\u0432\u0430 \u0421\u0428\u0410 \u0441 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u043c\u0438 \u0441\u043e\u044e\u0437\u043d\u0438\u043a\u0430\u043c\u0438 \u000d\u000a\u0432 \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u043c \u0437\u0430\u043b\u0438\u0432\u0435 \u043d\u0430 \u0444\u043e\u043d\u0435 \u043d\u0435\u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435.\u000d\u000a\u0413\u043e\u0441\u0434\u0435\u043f\u0430\u0440\u0442\u0430\u043c\u0435\u043d\u0442 \u0421\u0428\u0410 \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u000d\u000a\u043e\u0431\u043e\u0440\u043e\u043d\u043d\u044b\u0435 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442\u044b \u0441 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0435\u0439 \u000d\u000a\u0438 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u043e\u043c \u043d\u0430 \u043e\u0431\u0449\u0443\u044e \u0441\u0443\u043c\u043c\u0443 \u043e\u043a\u043e\u043b\u043e $1,5 \u043c\u043b\u0440\u0434. \u000a\u000d\u000a\u0420\u0435\u0447\u044c \u0438\u0434\u0435\u0442 \u043e \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u000d\u000a\u0443\u0441\u043b\u0443\u0433 \u043f\u043e \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044e \u0438 \u0441\u043e\u043f\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0433\u043e \u000d\u000a\u043e\u0431\u043e\u0440\u0443\u0434\u043e\u0432\u0430\u043d\u0438\u044f \u0434\u043b\u044f \u0432\u043e\u0435\u043d\u043d\u044b\u0445 \u0432\u0435\u0440\u0442\u043e\u043b\u0435\u0442\u043e\u0432 \u2028\u000d\u000a\u043d\u0430 $1 \u043c\u043b\u0440\u0434.\u000d\u000a\u043e\u0434\u043e\u0431\u0440\u0438\u043b \u0413\u043e\u0441\u0434\u0435\u043f\u0430\u0440\u0442\u0430\u043c\u0435\u043d\u0442 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u0441 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u043e\u043c \u000d\u000a\u043f\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0435 \u0438 \u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u043d\u0438\u044e \u0438\u0441\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u0435\u0439 F-16 \u000d\u000a\u043d\u0430 \u0441\u0443\u043c\u043c\u0443 $455 \u043c\u043b\u043d. \u041e\u0441\u043d\u043e\u0432\u043d\u044b\u043c\u0438 \u043f\u043e\u0434\u0440\u044f\u0434\u0447\u0438\u043a\u0430\u043c\u0438 \u000d\u000a\u0432\u044b\u0441\u0442\u0443\u043f\u044f\u0442 General Electric Aerospace \u2028\u000d\u000a\u0438 Lockheed Martin Aeronautics.\u000d\u000a\u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u043b \u000d\u000a03 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 28 \u043d\u043e\u044f\u0431\u0440\u044f \u2014 5 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000a\u0415\u0433\u0438\u043f\u0435\u0442 \u0445\u043e\u0447\u0435\u0442 \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u044c \u0432 \u043e\u0442\u0440\u0430\u0441\u043b\u044c \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0447\u0438 \u000d\u000a\u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0445 \u0438\u0433\u0440\u043e\u043a\u043e\u0432\u000d\u000a\u0412\u043b\u0430\u0441\u0442\u0438 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u044e\u0442 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442\u044c \u0434\u043e\u043b\u044e \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0433\u043e \u0441\u0435\u043a\u0442\u043e\u0440\u0430 \u0432 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0435 \u0441 1% \u0434\u043e 6% \u000d\u000a\u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 10 \u043b\u0435\u0442.\u000d\u000a\u0415\u0433\u0438\u043f\u0435\u0442 \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0439 \u043f\u043e\u0440\u0442\u0430\u043b, \u0447\u0442\u043e\u0431\u044b \u043f\u0440\u0438\u0432\u043b\u0435\u0447\u044c \u000d\u000a\u043d\u0435\u0431\u043e\u043b\u044c\u0448\u0438\u0435 \u0438 \u0441\u0440\u0435\u0434\u043d\u0438\u0435 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0435 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0434\u043b\u044f \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0438 \u043d\u0435\u043e\u0441\u0432\u043e\u0435\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u0430, \u043c\u0438\u043d\u0438\u0441\u0442\u0440 \u000d\u000a\u043d\u0435\u0444\u0442\u0438 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u041a\u0430\u0440\u0438\u043c \u0411\u0430\u0434\u0430\u0432\u0438.\u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b\u000d\u000a\u041f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u043e \u0441\u043d\u0438\u0437\u0438\u0442\u044c \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u044b\u0435 \u000d\u000a\u0441\u0431\u043e\u0440\u044b \u0438 \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u044d\u0442\u0430\u043f\u044b \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0438 \u0431\u043e\u043b\u0435\u0435 \u000d\u000a\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u043c\u0438 \u0437\u0430 \u0441\u0447\u0435\u0442 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u000d\u000a\u043f\u0435\u0440\u0432\u043e\u043d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u0442\u0440\u0430\u0442. \u0412 \u0440\u0430\u043c\u043a\u0430\u0445 \u0438\u043d\u0438\u0446\u0438\u0430\u0442\u0438\u0432\u044b \u000d\u000a\u043f\u0440\u0435\u0434\u0443\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u044b \u043d\u0430\u043b\u043e\u0433\u043e\u0432\u044b\u0435 \u0438 \u0442\u0430\u043c\u043e\u0436\u0435\u043d\u043d\u044b\u0435 \u000d\u000a\u043b\u044c\u0433\u043e\u0442\u044b \u043d\u0430 \u043e\u0431\u043e\u0440\u0443\u0434\u043e\u0432\u0430\u043d\u0438\u0435, \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044b \u0438 \u0443\u0441\u043b\u0443\u0433\u0438.\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0438\u0440\u0443\u0435\u0442 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u000d\u000a\u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430 \u0431\u044e\u0434\u0436\u0435\u0442\u0430 \u0432 2026 \u0433\u043e\u0434\u0443\u000d\u000a\u041a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u0443\u0435\u0442 \u0440\u0430\u0441\u0445\u043e\u0434\u044b \u043d\u0430 \u0444\u043e\u043d\u0435 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u044f \u043d\u0435\u0444\u0442\u044f\u043d\u044b\u0445 \u0434\u043e\u0445\u043e\u0434\u043e\u0432. \u0420\u0430\u043d\u0435\u0435 \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u000d\u000aSaudi Aramco \u0443\u043f\u0430\u043b\u0430 \u043f\u043e\u0447\u0442\u0438 \u043d\u0430 10% \u0437\u0430 \u0434\u0435\u0432\u044f\u0442\u044c \u043c\u0435\u0441\u044f\u0446\u0435\u0432 2025 \u0433\u043e\u0434\u0430. \u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u000d\u000a\u0431\u044e\u0434\u0436\u0435\u0442\u0430 \u0432 2026 \u0433\u043e\u0434\u0443 \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 $44,1 \u043c\u043b\u0440\u0434 \u000d\u000a(3,3% \u0412\u0412\u041f) \u043f\u0440\u043e\u0442\u0438\u0432 $65,3 \u043c\u043b\u0440\u0434 (5,3% \u0412\u0412\u041f) \u2028\u000d\u000a\u0432 2025 \u0433\u043e\u0434\u0443, \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u0443 \u0431\u044e\u0434\u0436\u0435\u0442\u0430, \u000d\u000a\u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u043e\u043c\u0443 \u041c\u0438\u043d\u0444\u0438\u043d\u043e\u043c.\u000d\u000a\u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0438\u0440\u0443\u0435\u0442 \u0412 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0435 \u0443\u043a\u0430\u0437\u0430\u043d\u043e, \u0447\u0442\u043e \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u043e\u0441\u0442\u0430\u043d\u0435\u0442\u0441\u044f \u000d\u000a\u043d\u0438\u0437\u043a\u0438\u043c \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u043c\u0435\u0440\u0430\u043c \u043f\u043e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044e \u000d\u000a\u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432.\u000d\u000a04 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 28 \u043d\u043e\u044f\u0431\u0440\u044f \u2014 5 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000aDP World \u043d\u0430\u0447\u0430\u043b \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u043e\u0439 \u000d\u000a\u043b\u0438\u043d\u0438\u0438 \u0432 \u0430\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u0439\u0441\u043a\u043e\u043c \u043f\u043e\u0440\u0442\u0443\u000d\u000a\u041f\u0440\u043e\u0435\u043a\u0442 \u2014 \u0447\u0430\u0441\u0442\u044c \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432 DP World \u043d\u0430 $1 \u043c\u043b\u0440\u0434 \u043f\u043e \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u043f\u043e\u0440\u0442\u043e\u0432\u043e\u0439 \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u0410\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u0438 \u043a 2028 \u0433\u043e\u0434\u0443.\u000d\u000a\u042d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u0438\u0439 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440 DP World \u000d\u000a \u043a \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443 \u043d\u043e\u0432\u043e\u0439 \u000d\u000a\u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u043e\u0439 \u043b\u0438\u043d\u0438\u0438 \u0437\u0430 $18 \u043c\u043b\u043d \u000d\u000a\u0432 \u0430\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u0439\u0441\u043a\u043e\u043c \u043f\u043e\u0440\u0442\u0443 \u0424\u0440\u0438\u043c\u0430\u043d\u0442\u043b. \u000a\u000d\u000a\u041f\u0440\u043e\u0435\u043a\u0442 Fremantle Rail Interchange \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u000d\u000a\u0441\u0432\u044f\u0436\u0435\u0442 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u043d\u044b\u0439 \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b DP World \u000d\u000a\u0441 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u043c \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u044b\u043c \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u043e\u043c\u000d\u000a\u043f\u0440\u0438\u0441\u0442\u0443\u043f\u0438\u043b\u000d\u000a\u043f\u043e\u0440\u0442\u0430. \u042d\u0442\u043e \u0443\u0441\u043a\u043e\u0440\u0438\u0442 \u043f\u0435\u0440\u0435\u0432\u0430\u043b\u043a\u0443 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u043e\u0432 \u000d\u000a\u0438 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u0442 \u043d\u0430\u0433\u0440\u0443\u0437\u043a\u0443 \u043d\u0430 \u0434\u043e\u0440\u043e\u0436\u043d\u0443\u044e \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u043f\u043e\u0440\u0442\u0430.\u000a\u000d\u000aDP World \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0438\u0440\u0443\u0435\u0442, \u0447\u0442\u043e \u0437\u0430\u043f\u0443\u0441\u043a \u043b\u0438\u043d\u0438\u0438 \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0438\u0442 \u0434\u043e\u043b\u044e \u0433\u0440\u0443\u0437\u043e\u043f\u0435\u0440\u0435\u0432\u043e\u0437\u043e\u043a \u043f\u043e \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0439 \u000d\u000a\u0434\u043e\u0440\u043e\u0433\u0435 \u0441 22% \u0434\u043e 33%.\u000d\u000a#\u043e\u0431\u0449\u0435\u0441\u0442\u0432\u043e\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u044f \u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043b\u0438 \u2028\u000d\u000a\u0432\u0437\u0430\u0438\u043c\u043d\u0443\u044e \u043e\u0442\u043c\u0435\u043d\u0443 \u0432\u0438\u0437\u000d\u000a\u042d\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0430\u043c \u043e\u0431\u0435\u0438\u0445 \u0441\u0442\u0440\u0430\u043d \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u044c\u0441\u044f \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0430 \u0434\u043e 90 \u0434\u043d\u0435\u0439 \u0432 \u0433\u043e\u0434\u0443 \u000d\u000a\u0438 \u0432\u044a\u0435\u0437\u0436\u0430\u0442\u044c \u043f\u0440\u0438 \u043f\u043e\u043c\u043e\u0449\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0433\u043e \u043f\u0430\u0441\u043f\u043e\u0440\u0442\u0430.\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u044f \u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u000d\u000a\u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e\u0431 \u043e\u0442\u043c\u0435\u043d\u0435 \u0432\u0438\u0437\u043e\u0432\u043e\u0433\u043e \u0440\u0435\u0436\u0438\u043c\u0430 \u000d\u000a\u0434\u043b\u044f \u0432\u043b\u0430\u0434\u0435\u043b\u044c\u0446\u0435\u0432 \u0432\u0441\u0435\u0445 \u0442\u0438\u043f\u043e\u0432 \u043f\u0430\u0441\u043f\u043e\u0440\u0442\u043e\u0432.\u000a\u000d\u000a\u0421\u0435\u0439\u0447\u0430\u0441 \u0434\u043b\u044f \u043f\u043e\u0441\u0435\u0449\u0435\u043d\u0438\u044f \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u000d\u000a\u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0430\u043c \u0420\u043e\u0441\u0441\u0438\u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f \u0432\u0438\u0437\u0430, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u000d\u000a\u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b\u0438 \u0434\u0430\u0435\u0442 \u043f\u0440\u0430\u0432\u043e \u043d\u0430 \u043f\u0440\u0435\u0431\u044b\u0432\u0430\u043d\u0438\u0435 \u0432 \u0441\u0442\u0440\u0430\u043d\u0435 \u0434\u043e 90 \u0434\u043d\u0435\u0439 \u000d\u000a\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u0433\u043e\u0434\u0430 \u0441 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c\u044e \u000d\u000a\u043c\u043d\u043e\u0433\u043e\u043a\u0440\u0430\u0442\u043d\u043e\u0433\u043e \u0432\u044a\u0435\u0437\u0434\u0430.\u000d\u000a05 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 28 \u043d\u043e\u044f\u0431\u0440\u044f \u2014 5 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0415\u0433\u0438\u043f\u0435\u0442 \u043e\u0436\u0438\u0434\u0430\u0435\u0442 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u0442\u0440\u0430\u043d\u0437\u0438\u0442\u0430 \u000d\u000a\u0447\u0435\u0440\u0435\u0437 \u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u043a\u0430\u043d\u0430\u043b\u000d\u000a\u041c\u0435\u043d\u0435\u0434\u0436\u043c\u0435\u043d\u0442 \u043a\u0430\u043d\u0430\u043b\u0430 \u043f\u043e\u043b\u0430\u0433\u0430\u0435\u0442, \u0447\u0442\u043e \u0433\u043e\u0434\u043e\u0432\u044b\u0435 \u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u044f \u043f\u0440\u0435\u0432\u044b\u0441\u044f\u0442 $4 \u043c\u043b\u0440\u0434 \u0438 \u0432 2026 \u0433\u043e\u0434\u0443 \u000d\u000a\u043f\u0440\u0438\u0431\u043b\u0438\u0437\u044f\u0442\u0441\u044f \u043a \u0434\u043e\u043a\u0440\u0438\u0437\u0438\u0441\u043d\u044b\u043c $10 \u043c\u043b\u0440\u0434.\u000d\u000a\u0413\u043b\u0430\u0432\u0430 \u0423\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u043a\u0430\u043d\u0430\u043b\u0430 \u0423\u0441\u0430\u043c\u0430 \u0420\u0430\u0431\u0438\u0430 \u000d\u000a\u0432 \u0438\u043d\u0442\u0435\u0440\u0432\u044c\u044e \u0442\u0435\u043b\u0435\u043a\u0430\u043d\u0430\u043b\u0443 Asharq , \u0447\u0442\u043e \u000d\u000a\u0442\u0440\u0430\u043d\u0437\u0438\u0442 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u043f\u043e\u044d\u0442\u0430\u043f\u043d\u043e. \u041f\u043e \u0435\u0433\u043e \u000d\u000a\u0441\u043b\u043e\u0432\u0430\u043c, \u0441\u0430\u043c\u043c\u0438\u0442 \u0432 \u0428\u0430\u0440\u043c-\u044d\u0448-\u0428\u0435\u0439\u0445\u0435 \u000d\u000a\u043f\u043e \u0443\u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e \u043f\u0430\u043b\u0435\u0441\u0442\u0438\u043d\u043e-\u0438\u0437\u0440\u0430\u0438\u043b\u044c\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u043f\u043e\u043c\u043e\u0433 \u0441\u0442\u0430\u0431\u0438\u043b\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044e.\u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b\u000d\u000a\u041d\u0430 \u0444\u043e\u043d\u0435 \u043a\u0440\u0438\u0437\u0438\u0441\u0430 \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u0447\u0438\u043a\u0438 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u043b\u0438 \u000d\u000a\u0433\u0440\u0443\u0437\u044b \u0432\u043e\u043a\u0440\u0443\u0433 \u043c\u044b\u0441\u0430 \u0414\u043e\u0431\u0440\u043e\u0439 \u041d\u0430\u0434\u0435\u0436\u0434\u044b, \u0447\u0442\u043e \u000d\u000a\u043f\u043e\u0432\u044b\u0448\u0430\u043b\u043e \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u0440\u0435\u0439\u0441\u043e\u0432. \u0414\u043e\u0445\u043e\u0434\u044b \u043a\u0430\u043d\u0430\u043b\u0430 \u000d\u000a\u0432 \u043e\u043a\u0442\u044f\u0431\u0440\u0435 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0438 $373 \u043c\u043b\u043d, \u0432 \u043d\u043e\u044f\u0431\u0440\u0435 \u2014 \u000d\u000a$383 \u043c\u043b\u043d.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0430\u044f Investcorp \u0441\u0442\u0430\u043b\u0430 \u044f\u043a\u043e\u0440\u043d\u044b\u043c \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u043c \u000d\u000aIPO Chuangxin Industries\u000d\u000a\u041f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u0441\u0440\u0435\u0434\u0441\u0442\u0432 \u043f\u043e\u0439\u0434\u0435\u0442 \u043d\u0430 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u043e\u0433\u043e \u0437\u0430\u0432\u043e\u0434\u0430 \u0432 \u0433\u043e\u0440\u043e\u0434\u0435 \u042f\u043d\u0431\u0443 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u000d\u000a\u0410\u0440\u0430\u0432\u0438\u0438. \u0414\u0440\u0443\u0433\u0430\u044f \u2014 \u0432 \u043f\u0435\u0440\u0435\u0445\u043e\u0434 \u043d\u0430 \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0435\u043c\u044b\u0435 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438 \u044d\u043d\u0435\u0440\u0433\u0438\u0438. \u000d\u000aInvestcorp \u044f\u043a\u043e\u0440\u043d\u044b\u043c \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u043e\u043c IPO \u000d\u000a\u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 Chuangxin Industries \u043d\u0430 \u0413\u043e\u043d\u043a\u043e\u043d\u0433\u0441\u043a\u043e\u0439 \u000d\u000a\u0431\u0438\u0440\u0436\u0435. Chuangxin \u043f\u0440\u0438\u0432\u043b\u0435\u043a\u043b\u0430 $813 \u043c\u043b\u043d \u0447\u0435\u0440\u0435\u0437 \u000d\u000a\u0444\u043e\u043d\u0434 Golden Horizon Cooperation Fund.\u000d\u000a\u0441\u0442\u0430\u043b\u0430 Chuangxin \u0432\u043b\u0430\u0434\u0435\u0435\u0442 \u0433\u043b\u0438\u043d\u043e\u0437\u0435\u043c\u043d\u044b\u043c \u0437\u0430\u0432\u043e\u0434\u043e\u043c \u000d\u000a\u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u0428\u0430\u043d\u044c\u0434\u0443\u043d \u0438 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u043c \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e\u043c \u0432\u043e \u0412\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0435\u0439 \u041c\u043e\u043d\u0433\u043e\u043b\u0438\u0438. \u000d\u000a\u0412 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0442\u0447\u0438\u0442\u0430\u043b\u0430\u0441\u044c \u000d\u000a\u043e \u0432\u044b\u0440\u0443\u0447\u043a\u0435 \u0432 \u0440\u0430\u0437\u043c\u0435\u0440\u0435 $2,1 \u043c\u043b\u0440\u0434.\u000d\u000a#\u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u0438\u000d\u000a16 \u0434\u0435\u043a\u0430\u0431\u0440\u044f, \u041d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0435\u043d\u044c \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430\u000d\u000a\u041f\u0440\u0430\u0437\u0434\u043d\u0438\u043a \u043f\u043e\u0441\u0432\u044f\u0449\u0435\u043d \u043e\u0441\u0432\u043e\u0431\u043e\u0436\u0434\u0435\u043d\u0438\u044e \u043e\u0442 \u0431\u0440\u0438\u0442\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0442\u0435\u043a\u0442\u043e\u0440\u0430\u0442\u0430.\u000d\u000a06 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 28 \u043d\u043e\u044f\u0431\u0440\u044f \u2014 5 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041e\u0441\u043d\u043e\u0432\u0430\u0442\u0435\u043b\u044c Zijin Mining \u043f\u043e\u043a\u0438\u043d\u0435\u0442 \u043f\u043e\u0441\u0442 \u2028\u000d\u000a\u043f\u0440\u0435\u0434\u0441\u0435\u0434\u0430\u0442\u0435\u043b\u044f \u0441\u043e\u0432\u0435\u0442\u0430 \u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440\u043e\u0432\u000d\u000a\u0415\u0433\u043e \u043f\u0440\u0435\u0435\u043c\u043d\u0438\u043a\u0430 \u043f\u043e\u043a\u0430 \u043d\u0435 \u043d\u0430\u0437\u0432\u0430\u043b\u0438. Zijin Mining \u2014 \u043e\u0434\u0438\u043d \u0438\u0437 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0442\u0447\u0438\u043a\u043e\u0432. \u000d\u000a\u041e\u0441\u043d\u043e\u0432\u0430\u0442\u0435\u043b\u044c Zijin Mining \u0427\u044d\u043d\u044c \u0426\u0437\u0438\u043d\u0445\u044d \u000d\u000a\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u0438 \u043f\u043e\u043a\u0438\u043d\u0443\u0442\u044c \u043f\u043e\u0441\u0442 \u043f\u0440\u0435\u0434\u0441\u0435\u0434\u0430\u0442\u0435\u043b\u044f \u0441\u043e\u0432\u0435\u0442\u0430 \u000d\u000a\u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440\u043e\u0432 \u043f\u043e \u0432\u043e\u0437\u0440\u0430\u0441\u0442\u0443 \u0438 \u0441\u0435\u043c\u0435\u0439\u043d\u044b\u043c \u000d\u000a\u043e\u0431\u0441\u0442\u043e\u044f\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430\u043c. \u041e\u043d \u0441\u0442\u0430\u043d\u0435\u0442 \u043f\u043e\u0447\u0435\u0442\u043d\u044b\u043c \u000d\u000a\u043f\u0440\u0435\u0434\u0441\u0435\u0434\u0430\u0442\u0435\u043b\u0435\u043c \u0438 \u0441\u0442\u0430\u0440\u0448\u0438\u043c \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u043d\u0442\u043e\u043c.\u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0430 \u0432 1986 \u0433\u043e\u0434\u0443 \u0438 \u043d\u0430\u0447\u0438\u043d\u0430\u043b\u0430 \u000d\u000a\u0441 \u043d\u0435\u0431\u043e\u043b\u044c\u0448\u043e\u0439 \u0448\u0430\u0445\u0442\u044b \u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u0437\u043e\u043b\u043e\u0442\u0430. \u042d\u0442\u043e\u0439 \u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b \u043e\u0441\u0435\u043d\u044c\u044e \u0435\u0435 \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043f\u0440\u0435\u0432\u044b\u0441\u0438\u043b\u0430 \u043e\u0442\u043c\u0435\u0442\u043a\u0443 \u000d\u000a$100 \u043c\u043b\u0440\u0434, \u0447\u0442\u043e \u0441\u0434\u0435\u043b\u0430\u043b\u043e \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044e \u0442\u0440\u0435\u0442\u044c\u0435\u0439 \u000d\u000a\u043f\u043e \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u0435 \u0432 \u0441\u0435\u043a\u0442\u043e\u0440\u0435 \u043f\u043e\u0441\u043b\u0435 BHP \u0438 Rio Tinto. \u000d\u000aZijin \u0441\u043c\u0435\u0441\u0442\u0438\u043b\u0430 \u0441 \u0442\u0440\u0435\u0442\u044c\u0435\u0439 \u0441\u0442\u0440\u043e\u0447\u043a\u0438 Glencore. \u000d\u000a\u0412 2025 \u0433\u043e\u0434\u0443 \u0430\u043a\u0446\u0438\u0438 Zijin Mining \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u0432 \u0446\u0435\u043d\u0435 \u000d\u000a\u0431\u043e\u043b\u0435\u0435 \u0447\u0435\u043c \u0432 \u0434\u0432\u0430 \u0440\u0430\u0437\u0430.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f\u000d\u000a\u0411\u0438\u0440\u0436\u0430 \u0413\u0443\u0430\u043d\u0447\u0436\u043e\u0443 \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b\u0430 \u0442\u043e\u0440\u0433\u0438 \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u0430\u043c\u0438 \u000d\u000a\u043d\u0430 \u043f\u043b\u0430\u0442\u0438\u043d\u0443 \u0438 \u043f\u0430\u043b\u043b\u0430\u0434\u0438\u0439\u000d\u000a\u041e\u0431\u043e\u0440\u043e\u0442 \u0442\u043e\u0440\u0433\u043e\u0432 \u043f\u043e \u044d\u0442\u0438\u043c \u043c\u0435\u0442\u0430\u043b\u043b\u0430\u043c \u0434\u043e\u0441\u0442\u0438\u0433 \u043f\u043e\u0447\u0442\u0438 $6 \u043c\u043b\u0440\u0434 \u0437\u0430 \u0434\u0435\u043d\u044c.\u000d\u000aGFEX \u0442\u043e\u0440\u0433\u0438 \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u0430\u043c\u0438 \u043d\u0430 \u043f\u043b\u0430\u0442\u0438\u043d\u0443 \u000d\u000a\u0438 \u043f\u0430\u043b\u043b\u0430\u0434\u0438\u0439. \u0422\u043e\u0440\u0433\u0438 \u043f\u043b\u0430\u0442\u0438\u043d\u043e\u0439 \u0437\u0430 \u043f\u0435\u0440\u0432\u044b\u0439 \u0434\u0435\u043d\u044c \u000d\u000a\u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0438 29,2 \u043c\u043b\u0440\u0434 \u044e\u0430\u043d\u0435\u0439 ($4,13 \u043c\u043b\u0440\u0434), \u000d\u000a\u043f\u0430\u043b\u043b\u0430\u0434\u0438\u0435\u043c \u2014 13,05 \u043c\u043b\u0440\u0434 \u044e\u0430\u043d\u0435\u0439 ($1,85 \u043c\u043b\u0440\u0434).\u000d\u000a\u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b\u0430 \u0411\u0438\u0440\u0436\u0430 \u043e\u0442\u043a\u0440\u044b\u043b\u0430\u0441\u044c \u0432 2021 \u0433\u043e\u0434\u0443 \u0438 \u043f\u043e\u0441\u0442\u0435\u043f\u0435\u043d\u043d\u043e \u000d\u000a\u0440\u0430\u0441\u0448\u0438\u0440\u044f\u0435\u0442 \u043b\u0438\u043d\u0435\u0439\u043a\u0443 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432.\u000d\u000a#\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f\u000d\u000aFESCO \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b\u0430 \u0433\u0440\u0443\u0437\u043e\u0432\u043e\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u0438\u0437 \u0421\u0438\u0430\u043d\u044f \u000d\u000a\u0432 \u0421\u0430\u043d\u043a\u0442-\u041f\u0435\u0442\u0435\u0440\u0431\u0443\u0440\u0433\u000d\u000a\u041f\u0435\u0440\u0432\u044b\u0439 \u0441\u043e\u0441\u0442\u0430\u0432 \u043f\u0440\u043e\u0448\u0435\u043b \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u0437\u0430 15 \u0441\u0443\u0442\u043e\u043a.\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u0430\u044f \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u043d\u0430\u044f \u0433\u0440\u0443\u043f\u043f\u0430 FESCO \u000d\u000a \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u044b\u0439 \u0441\u0435\u0440\u0432\u0438\u0441 \u0434\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u0433\u0440\u0443\u0437\u043e\u0432 \u0447\u0435\u0440\u0435\u0437 \u041a\u0430\u0437\u0430\u0445\u0441\u0442\u0430\u043d. \u041f\u043e\u0435\u0437\u0434 \u000d\u000a\u0441 \u0441\u043e\u0440\u043e\u043a\u0430\u0444\u0443\u0442\u043e\u0432\u044b\u043c\u0438 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u0430\u043c\u0438 \u043f\u0440\u043e\u0448\u0435\u043b \u0447\u0435\u0440\u0435\u0437\u000d\u000a\u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b\u0430\u000d\u000a\u043f\u043e\u0433\u0440\u0430\u043d\u043f\u0435\u0440\u0435\u0445\u043e\u0434 \u0410\u043b\u0430\u0448\u0430\u043d\u044c\u043a\u043e\u0443 \u2014 \u0414\u043e\u0441\u0442\u044b\u043a \u0438 \u0434\u0430\u043b\u0435\u0435 \u000d\u000a\u043f\u043e \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0420\u043e\u0441\u0441\u0438\u0438. \u041d\u0430 \u0441\u0442\u0430\u0440\u0442\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u000d\u000a\u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0435\u0439\u0441 \u0432 \u043c\u0435\u0441\u044f\u0446, \u0437\u0430\u0442\u0435\u043c \u0434\u0432\u0430.\u000d\u000a07 09","\u041a\u0438\u0442\u0430\u0439 28 \u043d\u043e\u044f\u0431\u0440\u044f \u2014 5 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0440\u044b\u043d\u043a\u0438\u000d\u000a\u0410\u043a\u0446\u0438\u0438 China Uranium \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043f\u043e\u0447\u0442\u0438 \u0432 \u0447\u0435\u0442\u044b\u0440\u0435 \u0440\u0430\u0437\u0430 \u000d\u000a\u043f\u043e\u0441\u043b\u0435 \u0434\u0435\u0431\u044e\u0442\u0430 \u043d\u0430 \u0428\u044d\u043d\u044c\u0447\u0436\u044d\u043d\u044c\u0441\u043a\u043e\u0439 \u0431\u0438\u0440\u0436\u0435\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0435 \u0443\u0440\u0430\u043d\u043e\u0432\u043e\u0435 IPO \u041a\u0438\u0442\u0430\u044f \u043f\u0440\u043e\u0448\u043b\u043e \u043d\u0430 \u0444\u043e\u043d\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u044f \u0430\u0442\u043e\u043c\u043d\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u0438 \u0440\u043e\u0441\u0442\u0430 \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u0446\u0435\u043d \u043d\u0430 \u0443\u0440\u0430\u043d.\u000d\u000aChina Uranium Corporation, \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0432 \u041a\u041d\u0420 \u0441 \u043f\u0440\u0430\u0432\u043e\u043c \u0434\u043e\u0431\u044b\u0447\u0438 \u0443\u0440\u0430\u043d\u0430, \u000d\u000a 4,44 \u043c\u043b\u0440\u0434 \u044e\u0430\u043d\u0435\u0439 (\u043e\u043a\u043e\u043b\u043e $570 \u043c\u043b\u043d) \u000d\u000a\u0432 \u0445\u043e\u0434\u0435 \u043b\u0438\u0441\u0442\u0438\u043d\u0433\u0430 \u043d\u0430 \u0428\u044d\u043d\u044c\u0447\u0436\u044d\u043d\u044c\u0441\u043a\u043e\u0439 \u0431\u0438\u0440\u0436\u0435. \u000d\u000a\u0426\u0435\u043d\u0430 \u0430\u043a\u0446\u0438\u0439 \u043d\u0430 \u043e\u0442\u043a\u0440\u044b\u0442\u0438\u0438 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u0441 17,89 \u000d\u000a\u0434\u043e \u043f\u043e\u0447\u0442\u0438 62 \u044e\u0430\u043d\u0435\u0439, \u0437\u0430\u0442\u0435\u043c \u043a\u0440\u0430\u0442\u043a\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u000d\u000a\u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0430 80 \u044e\u0430\u043d\u0435\u0439 \u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043b\u0430 \u0442\u043e\u0440\u0433\u0438 \u000d\u000a\u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 67,99 \u044e\u0430\u043d\u044f \u2014 \u0440\u043e\u0441\u0442 \u043d\u0430 280%. \u000d\u000a\u0420\u044b\u043d\u043e\u0447\u043d\u0430\u044f \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0430 \u000d\u000a140,6 \u043c\u043b\u0440\u0434 \u044e\u0430\u043d\u0435\u0439. \u0410\u043d\u0434\u0435\u0440\u0440\u0430\u0439\u0442\u0435\u0440\u043e\u043c \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u044f \u000d\u000a\u0432\u044b\u0441\u0442\u0443\u043f\u0438\u043b\u0430 CITIC Securities.\u000a\u000d\u000a\u041f\u043e\u043b\u0443\u0447\u0435\u043d\u043d\u044b\u0435 \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u044f\u0442 \u043d\u0430 \u0441\u0435\u043c\u044c \u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0434\u043e\u0431\u044b\u0447\u0443 \u0443\u0440\u0430\u043d\u0430 \u043c\u0435\u0442\u043e\u0434\u043e\u043c \u000d\u000a\u043f\u043e\u0434\u0437\u0435\u043c\u043d\u043e\u0433\u043e \u0432\u044b\u0449\u0435\u043b\u0430\u0447\u0438\u0432\u0430\u043d\u0438\u044f \u0432\u043e \u0412\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0435\u0439 \u000d\u000a\u041c\u043e\u043d\u0433\u043e\u043b\u0438\u0438, \u0421\u0438\u043d\u044c\u0446\u0437\u044f\u043d\u0435, \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u044f\u0445 \u0413\u0443\u0430\u043d\u0434\u0443\u043d \u000d\u000a\u0438 \u0426\u0437\u044f\u043d\u0441\u0438, \u0430 \u0442\u0430\u043a\u0436\u0435 \u043d\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043d\u043e\u0432\u044b\u0445 \u000d\u000a\u043f\u0440\u0438\u0432\u043b\u0435\u043a\u043b\u0430\u000d\u000a\u0442\u0430\u043d\u0442\u0430\u043b-\u043d\u0438\u043e\u0431\u0438\u0435\u0432\u044b\u0445 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u0432\u043b\u0430\u0434\u0435\u0435\u0442 19 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044f\u043c\u0438 \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u0438 6 \u2014 \u000d\u000a\u043d\u0430 \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443. China Uranium \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u000d\u000a\u0434\u043e\u0447\u0435\u0440\u043d\u0435\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0435\u0439 China National Nuclear \u000d\u000aCorporation \u0438 \u0432 2019 \u0433\u043e\u0434\u0443 \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u043b\u0430 69% \u000d\u000a\u0443\u0440\u0430\u043d\u043e\u0432\u043e\u0433\u043e \u0440\u0443\u0434\u043d\u0438\u043a\u0430 \u0420\u043e\u0441\u0441\u0438\u043d\u0433 \u0432 \u041d\u0430\u043c\u0438\u0431\u0438\u0438.\u000a\u000d\u000aIPO \u043f\u0440\u043e\u0448\u043b\u043e \u043d\u0430 \u0444\u043e\u043d\u0435 \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u044f \u000d\u000a\u0430\u0442\u043e\u043c\u043d\u043e\u0439 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438 \u0432 \u041a\u0438\u0442\u0430\u0435. \u0421\u0442\u0440\u0430\u043d\u0430 \u0443\u0436\u0435 \u0438\u043c\u0435\u0435\u0442 \u000d\u000a\u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0432 \u043c\u0438\u0440\u0435 \u043f\u043e\u0440\u0442\u0444\u0435\u043b\u044c \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0445 \u000d\u000a\u0438 \u0441\u0442\u0440\u043e\u044f\u0449\u0438\u0445\u0441\u044f \u0440\u0435\u0430\u043a\u0442\u043e\u0440\u043e\u0432 \u0438 \u043a 2030 \u0433\u043e\u0434\u0443 \u043c\u043e\u0436\u0435\u0442 \u000d\u000a\u043e\u0431\u043e\u0433\u043d\u0430\u0442\u044c \u0421\u0428\u0410 \u0438 \u0424\u0440\u0430\u043d\u0446\u0438\u044e \u043f\u043e \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u043c \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044f\u043c. \u0421\u043f\u0440\u043e\u0441 \u043d\u0430 \u0443\u0440\u0430\u043d \u0432 \u041a\u041d\u0420 \u043c\u043e\u0436\u0435\u0442 \u000d\u000a\u0443\u0442\u0440\u043e\u0438\u0442\u044c\u0441\u044f \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 15 \u043b\u0435\u0442, \u043f\u0440\u0438 \u0442\u043e\u043c \u0447\u0442\u043e \u0431\u043e\u043b\u0435\u0435 \u000d\u000a70% \u0442\u043e\u043f\u043b\u0438\u0432\u0430 \u0441\u0435\u0439\u0447\u0430\u0441 \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0438\u043c\u043f\u043e\u0440\u0442\u043e\u043c.\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u044f \u0432\u0432\u0435\u043b\u0430 \u0431\u0435\u0437\u0432\u0438\u0437\u043e\u0432\u044b\u0439 \u0440\u0435\u0436\u0438\u043c \u0434\u043b\u044f \u0433\u0440\u0430\u0436\u0434\u0430\u043d \u041a\u041d\u0420 \u000d\u000a\u0441\u0440\u043e\u043a\u043e\u043c \u0434\u043e 30 \u0434\u043d\u0435\u0439\u000d\u000a\u0420\u0435\u0436\u0438\u043c \u0431\u0443\u0434\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u0432 \u0442\u0435\u0441\u0442\u043e\u0432\u043e\u043c \u0440\u0435\u0436\u0438\u043c\u0435 \u0434\u043e \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u044f 2026 \u0433\u043e\u0434\u0430.\u000d\u000a\u041f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0420\u0424 \u0412\u043b\u0430\u0434\u0438\u043c\u0438\u0440 \u041f\u0443\u0442\u0438\u043d \u0443\u043a\u0430\u0437 \u000d\u000a\u043e \u0431\u0435\u0437\u0432\u0438\u0437\u043e\u0432\u043e\u043c \u0440\u0435\u0436\u0438\u043c\u0435 \u0434\u043b\u044f \u0433\u0440\u0430\u0436\u0434\u0430\u043d \u041a\u041d\u0420. \u000d\u000a\u041f\u043e\u0440\u044f\u0434\u043e\u043a \u043d\u0435 \u0440\u0430\u0441\u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u0442\u0440\u0443\u0434\u043e\u0432\u0443\u044e \u000d\u000a\u0438 \u0436\u0443\u0440\u043d\u0430\u043b\u0438\u0441\u0442\u0441\u043a\u0443\u044e \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c, \u0430 \u0442\u0430\u043a\u0436\u0435 \u000d\u000a\u043d\u0430 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435.\u000d\u000a\u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043b \u0420\u0430\u043d\u0435\u0435 \u041a\u0438\u0442\u0430\u0439 \u0432\u0432\u0435\u043b \u0430\u043d\u0430\u043b\u043e\u0433\u0438\u0447\u043d\u044b\u0439 \u0440\u0435\u0436\u0438\u043c \u0434\u043b\u044f \u000d\u000a\u0440\u043e\u0441\u0441\u0438\u044f\u043d, \u043e\u043d \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0441 15 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u044f.\u000d\u000a08 09","\u041a\u0438\u0442\u0430\u0439 28 \u043d\u043e\u044f\u0431\u0440\u044f \u2014 5 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f\u000d\u000a\u0417\u0430\u043f\u0430\u0441\u044b \u0437\u043e\u043b\u043e\u0442\u0430 \u0438 \u0441\u0435\u0440\u0435\u0431\u0440\u0430 \u043d\u0430 \u0441\u043a\u043b\u0430\u0434\u0430\u0445 \u0448\u0430\u043d\u0445\u0430\u0439\u0441\u043a\u0438\u0445 \u000d\u000a\u0431\u0438\u0440\u0436 \u0443\u043f\u0430\u043b\u0438 \u0434\u043e \u0434\u0435\u0441\u044f\u0442\u0438\u043b\u0435\u0442\u043d\u0435\u0433\u043e \u043c\u0438\u043d\u0438\u043c\u0443\u043c\u0430\u000d\u000a\u041f\u0430\u0434\u0435\u043d\u0438\u0435 \u0441\u0432\u044f\u0437\u0430\u043d\u043e \u0441 \u0440\u043e\u0441\u0442\u043e\u043c \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432.\u000d\u000a\u0417\u0430\u043f\u0430\u0441\u044b \u0437\u043e\u043b\u043e\u0442\u0430 \u043d\u0430 \u0441\u043a\u043b\u0430\u0434\u0430\u0445 SGE \u2028\u000d\u000a\u0434\u043e 519 \u0442\u043e\u043d\u043d \u2014 \u043c\u0438\u043d\u0438\u043c\u0443\u043c\u0430 \u0441 2015 \u0433\u043e\u0434\u0430. \u0417\u0430\u043f\u0430\u0441\u044b \u000d\u000a\u0441\u0435\u0440\u0435\u0431\u0440\u0430 \u043d\u0430 ShFE \u0443\u043f\u0430\u043b\u0438 \u0434\u043e 715 \u0442\u043e\u043d\u043d \u2014 \u043c\u0438\u043d\u0438\u043c\u0443\u043c\u0430 \u000d\u000a\u0437\u0430 \u0434\u0435\u0432\u044f\u0442\u044c \u043b\u0435\u0442. \u042d\u0442\u043e \u0441\u0432\u044f\u0437\u0430\u043d\u043e \u0441 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435\u043c \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 \u043d\u0430 \u041b\u043e\u043d\u0434\u043e\u043d\u0441\u043a\u0443\u044e \u0431\u0438\u0440\u0436\u0443 \u000d\u000a\u043c\u0435\u0442\u0430\u043b\u043b\u043e\u0432 (LME).\u000d\u000a\u0441\u043d\u0438\u0437\u0438\u043b\u0438\u0441\u044c \u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0439 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0437\u043e\u043b\u043e\u0442\u0430 \u0432 \u043e\u043a\u0442\u044f\u0431\u0440\u0435 \u0434\u043e\u0441\u0442\u0438\u0433 \u000d\u000a\u0440\u0435\u043a\u043e\u0440\u0434\u043d\u044b\u0445 660 \u0442\u043e\u043d\u043d.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aSolGold \u043e\u0442\u043a\u043b\u043e\u043d\u0438\u043b\u0430 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 Jiangxi Copper \u000d\u000a\u043e \u043f\u043e\u0433\u043b\u043e\u0449\u0435\u043d\u0438\u0438\u000d\u000a\u041a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u0430\u043a\u0442\u0438\u0432 SolGold \u2014 \u043e\u0434\u043d\u043e \u0438\u0437 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0445 \u0432 \u043c\u0438\u0440\u0435 \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0439 \u043c\u0435\u0434\u0438 \u0438 \u0437\u043e\u043b\u043e\u0442\u0430 \u000d\u000aCascabel \u0432 \u042d\u043a\u0432\u0430\u0434\u043e\u0440\u0435.\u000d\u000aSolGold \u0432\u0442\u043e\u0440\u043e\u0435 \u043f\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u000d\u000a\u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 Jiangxi \u000d\u000aCopper, \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u0430 \u0441 \u0434\u043e\u043b\u0435\u0439 12%. \u000d\u000a\u0422\u0435\u043f\u0435\u0440\u044c Jiangxi Copper \u0434\u043e 26 \u0434\u0435\u043a\u0430\u0431\u0440\u044f \u0434\u043e\u043b\u0436\u043d\u0430 \u000d\u000a\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0438\u0442\u044c, \u0431\u0443\u0434\u0435\u0442 \u043b\u0438 \u0434\u0435\u043b\u0430\u0442\u044c \u0442\u0432\u0435\u0440\u0434\u043e\u0435 \u000d\u000a\u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435. \u000a\u000d\u000a\u0421\u0440\u0435\u0434\u0438 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u0445 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u0435\u0439 \u000d\u000a\u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u043b\u0438\u0441\u044c BHP \u0438 Newmont, \u043d\u043e \u043e\u043d\u0438 \u000d\u000a\u043e\u0445\u043b\u0430\u0434\u0435\u043b\u0438 \u043a \u0441\u0434\u0435\u043b\u043a\u0435 \u0438\u0437 \u0437\u0430 \u0440\u0430\u0437\u043d\u043e\u0433\u043b\u0430\u0441\u0438\u0439 \u000d\u000a\u043f\u043e \u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0438 Cascabel.\u000d\u000a\u043e\u0442\u043a\u043b\u043e\u043d\u0438\u043b\u0430\u000d\u000a09 09"]